// Operation IDs are generated by the browser per confirmation and act as
// idempotency keys: storage accepts a repeated ID only with identical content.

func (a *api) deviceView(w http.ResponseWriter, r *http.Request) (storage.Device, devices.View, bool) {
	id := r.PathValue("id")
	if !protocol.ValidID(id) {
		apiError(w, http.StatusNotFound, "not_found", "Device not found.")
		return storage.Device{}, devices.View{}, false
	}
	d, err := a.store.Device(r.Context(), id)
	if errors.Is(err, storage.ErrAuthentication) {
		apiError(w, http.StatusNotFound, "not_found", "Device not found.")
		return d, devices.View{}, false
	}
	if err != nil {
		apiError(w, http.StatusServiceUnavailable, "unavailable", "The device is temporarily unavailable.")
		return d, devices.View{}, false
	}
	return d, devices.Present(d, time.Now(), a.offlineAfter()), true
}

// queueError maps storage refusals to responses the console can show as-is.
func queueError(w http.ResponseWriter, e error, refused error, message string) {
	switch {
	case errors.Is(e, storage.ErrForbidden):
		apiError(w, http.StatusForbidden, "forbidden", "Your permissions or device scope changed. Reload and retry.")
	case refused != nil && errors.Is(e, refused):
		apiError(w, http.StatusConflict, "refused", refused.Error())
	default:
		apiError(w, http.StatusServiceUnavailable, "unavailable", message)
	}
}

func registerDeviceToolsAPI(mux *http.ServeMux, a *api) {
	// Processes: the full bounded snapshot; the browser searches and sorts it.
	a.route(mux, "GET /api/v1/devices/{id}/processes", deviceAccess("read"), func(w http.ResponseWriter, r *http.Request, s storage.Session) {
		_, view, ok := a.deviceView(w, r)
		if !ok {
			return
		}
		now := time.Now()
		snapshot, e1 := a.store.Processes(r.Context(), view.ID)
		actions, e2 := a.store.ProcessActions(r.Context(), view.ID, now)
		if errors.Join(e1, e2) != nil {
			apiError(w, http.StatusServiceUnavailable, "unavailable", "Processes are temporarily unavailable.")
			return
		}
		pv := devices.PresentProcesses(snapshot, view, now)
		items := []protocol.Process{}
		if pv.Data != nil {
			items = pv.Data.Items
		}
		coverage, skipped := "", 0
		if pv.Data != nil {
			coverage, skipped = pv.Data.Coverage, pv.Data.Skipped
		}
		writeJSON(w, http.StatusOK, struct {
			Status     string                  `json:"status"`
			Stale      bool                    `json:"stale"`
			SnapshotAt *int64                  `json:"snapshot_at"`
			Coverage   string                  `json:"coverage"`
			Items      []protocol.Process      `json:"items"`
			Skipped    int                     `json:"skipped"`
			Actions    []storage.ProcessAction `json:"actions"`
			CanAct     bool                    `json:"can_act"`
		}{pv.Status, pv.Stale, pv.SnapshotAt, coverage, items, skipped, actions, s.Can("processes") && !pv.Stale})
	})
	a.route(mux, "POST /api/v1/devices/{id}/process-actions", deviceAccess("processes"), func(w http.ResponseWriter, r *http.Request, s storage.Session) {
		var in struct {
			ID    string `json:"id"`
			PID   uint32 `json:"pid"`
			Start string `json:"start"`
			Name  string `json:"name"`
		}
		if !decodeJSON(w, r, &in, 2048) {
			return
		}
		id := r.PathValue("id")
		if !protocol.ValidID(id) || !protocol.ValidID(in.ID) || !processes.Manageable(in.PID, in.Name) || !processes.Start(in.Start) {
			apiError(w, http.StatusBadRequest, "invalid_request", "This process cannot be ended.")
			return
		}
		e := a.store.QueueProcessAction(r.Context(), storage.ProcessAction{ProcessAction: protocol.ProcessAction{ID: in.ID, PID: in.PID, Start: in.Start, Name: in.Name}, DeviceID: id, Actor: s.Actor()}, time.Now(), a.offlineAfter())
		if e != nil {
			queueError(w, e, storage.ErrProcessAction, "Process actions are temporarily unavailable.")
			return
		}
		writeJSON(w, http.StatusAccepted, struct {
			ID string `json:"id"`
		}{in.ID})
	})

	// Services: the snapshot is part of device detail; this lists the actions.
	a.route(mux, "GET /api/v1/devices/{id}/service-actions", deviceAccess("read"), func(w http.ResponseWriter, r *http.Request, s storage.Session) {
		_, view, ok := a.deviceView(w, r)
		if !ok {
			return
		}
		items, e := a.store.ServiceActions(r.Context(), view.ID, time.Now())
		if e != nil {
			apiError(w, http.StatusServiceUnavailable, "unavailable", "Service actions are temporarily unavailable.")
			return
		}
		writeJSON(w, http.StatusOK, struct {
			Actions []storage.ServiceAction `json:"actions"`
			CanAct  bool                    `json:"can_act"`
		}{items, s.Can("services")})
	})
	a.route(mux, "POST /api/v1/devices/{id}/service-actions", deviceAccess("services"), func(w http.ResponseWriter, r *http.Request, s storage.Session) {
		var in struct {
			ID      string `json:"id"`
			Service string `json:"service"`
			Action  string `json:"action"`
		}
		if !decodeJSON(w, r, &in, 2048) {
			return
		}
		id := r.PathValue("id")
		if !protocol.ValidID(id) || !protocol.ValidID(in.ID) || !winservices.Manageable(in.Service) || !winservices.Action(in.Action) {
			apiError(w, http.StatusBadRequest, "invalid_request", "This service action is not allowed.")
			return
		}
		e := a.store.QueueServiceAction(r.Context(), storage.ServiceAction{ServiceAction: protocol.ServiceAction{ID: in.ID, Service: in.Service, Action: in.Action}, DeviceID: id, Actor: s.Actor()}, time.Now(), a.offlineAfter())
		if e != nil {
			queueError(w, e, storage.ErrAction, "Service actions are temporarily unavailable.")
			return
		}
		writeJSON(w, http.StatusAccepted, struct {
			ID string `json:"id"`
		}{in.ID})
	})

	// Event logs: queries are dispatched to the agent; results are retained for
	// fifteen minutes. Reading results requires the same Events permission as
	// starting a query.
	a.route(mux, "POST /api/v1/devices/{id}/event-logs", deviceAccess("events"), func(w http.ResponseWriter, r *http.Request, s storage.Session) {
		var in struct {
			ID     string `json:"id"`
			Filter struct {
				Channel  string `json:"channel"`
				From     int64  `json:"from"`
				To       int64  `json:"to"`
				Level    int    `json:"level"`
				Provider string `json:"provider"`
				EventID  int    `json:"event_id"`
				Before   uint64 `json:"before"`
				Limit    int    `json:"limit"`
				XPath    string `json:"xpath"`
			} `json:"filter"`
		}
		if !decodeJSON(w, r, &in, 16*1024) {
			return
		}
		// Pages of 25, 100 or 250 events; older clients send none.
		limit := in.Filter.Limit
		if limit == 0 {
			limit = eventlogs.MaxEventsV1
		}
		f := protocol.EventFilter{Channel: strings.TrimSpace(in.Filter.Channel), From: in.Filter.From, To: in.Filter.To, Level: in.Filter.Level, Provider: strings.TrimSpace(in.Filter.Provider), EventID: in.Filter.EventID, Before: in.Filter.Before, Limit: limit, XPath: strings.TrimSpace(in.Filter.XPath)}
		id := r.PathValue("id")
		if !protocol.ValidID(id) || !protocol.ValidID(in.ID) || !eventlogs.FilterValid(f) || limit != 25 && limit != 100 && limit != 250 {
			apiError(w, http.StatusBadRequest, "invalid_request", "Use a channel name, a time range up to 31 days, a valid level and event ID, a provider name without quotes, 25, 100 or 250 events, and an XPath of the form *[...].")
			return
		}
		// Raw XPath is for responders (the response permission).
		if f.XPath != "" && a.store.AuthorizeDevice(r.Context(), s, id, "response") != nil {
			apiError(w, http.StatusForbidden, "forbidden", "Raw XPath needs the response permission.")
			return
		}
		e := a.store.QueueEventQuery(r.Context(), storage.EventQuery{EventQuery: protocol.EventQuery{ID: in.ID, Filter: f}, DeviceID: id, Actor: s.Actor()}, time.Now(), a.offlineAfter())
		if e != nil {
			queueError(w, e, storage.ErrEventQuery, "Event queries are temporarily unavailable.")
			return
		}
		writeJSON(w, http.StatusAccepted, struct {
			ID string `json:"id"`
		}{in.ID})
	})
	a.route(mux, "GET /api/v1/devices/{id}/event-logs/{query}", deviceAccess("events"), func(w http.ResponseWriter, r *http.Request, s storage.Session) {
		id, qid := r.PathValue("id"), r.PathValue("query")
		if !protocol.ValidID(id) || !protocol.ValidID(qid) {
			apiError(w, http.StatusNotFound, "not_found", "Query not found.")
			return
		}
		q, e := a.store.EventQuery(r.Context(), id, qid, time.Now())
		if errors.Is(e, storage.ErrEventQuery) {
			apiError(w, http.StatusNotFound, "not_found", "This query has expired. Results are kept for 15 minutes.")
			return
		}
		if e != nil {
			apiError(w, http.StatusServiceUnavailable, "unavailable", "Event queries are temporarily unavailable.")
			return
		}
		writeJSON(w, http.StatusOK, q)
	})

	// Event log export: an .evtx file of a whole channel, or of the
	// events matching the current filter, collected into a case like any
	// evidence (response permission and device access).
	a.route(mux, "POST /api/v1/devices/{id}/event-logs/export", deviceAccess("response"), func(w http.ResponseWriter, r *http.Request, s storage.Session) {
		var in struct {
			CaseID    string                `json:"case_id"`
			CaseTitle string                `json:"case_title"`
			Channel   string                `json:"channel"`
			Filter    *protocol.EventFilter `json:"filter"`
		}
		if !decodeJSON(w, r, &in, 16*1024) {
			return
		}
		query, ok := exportQuery(in.Channel, in.Filter)
		if !ok || (in.CaseID == "") == (in.CaseTitle == "") || in.CaseID != "" && (!protocol.ValidID(in.CaseID) || in.CaseID == storage.LiveCase) {
			apiError(w, http.StatusBadRequest, "invalid_request", "Choose an open case or give a title for a new one, and use a channel name and valid filters.")
			return
		}
		if in.Filter != nil && in.Filter.XPath != "" && a.store.AuthorizeDevice(r.Context(), s, r.PathValue("id"), "response") != nil {
			apiError(w, http.StatusForbidden, "forbidden", "Raw XPath needs the response permission.")
			return
		}
		if in.CaseTitle != "" {
			c, e := a.store.CreateCase(r.Context(), in.CaseTitle, s.Actor(), time.Now())
			if e != nil {
				apiError(w, http.StatusBadRequest, "case", "The case title is invalid (1–200 characters, no line breaks).")
				return
			}
			in.CaseID = c.ID
		}
		id, e := a.store.QueueEventExport(r.Context(), in.CaseID, r.PathValue("id"), "", in.Channel, query, s.Actor(), time.Now())
		// A case created for an export that could not start is closed again.
		if e != nil && in.CaseTitle != "" {
			_ = a.store.SetCaseStatus(r.Context(), in.CaseID, "closed", s.Actor(), "Not used: the event log export could not start.", time.Now())
		}
		switch {
		case e == nil:
			writeJSON(w, http.StatusCreated, struct {
				ID     string `json:"id"`
				CaseID string `json:"case_id"`
			}{id, in.CaseID})
		case errors.Is(e, storage.ErrEventExport):
			apiError(w, http.StatusConflict, "agent", "The device's agent cannot export event logs yet; update it to the current release.")
		case errors.Is(e, storage.ErrEvidence):
			apiError(w, http.StatusConflict, "evidence", "Cannot export: check that the evidence store is configured, incident response is switched on for the device, and fewer than two collections are running on it.")
		case errors.Is(e, storage.ErrCase):
			apiError(w, http.StatusConflict, "case", "The case is closed or unknown.")
		default:
			apiError(w, http.StatusServiceUnavailable, "unavailable", "Event log export is temporarily unavailable.")
		}
	})

	// Software: the current list plus observed change history.
	a.route(mux, "GET /api/v1/devices/{id}/software", deviceAccess("read"), func(w http.ResponseWriter, r *http.Request, s storage.Session) {
		_, view, ok := a.deviceView(w, r)
		if !ok {
			return
		}
		now := time.Now()
		inv, e1 := a.store.Software(r.Context(), view.ID)
		history, e2 := a.store.SoftwareHistory(r.Context(), view.ID, now)
		if errors.Join(e1, e2) != nil {
			apiError(w, http.StatusServiceUnavailable, "unavailable", "Software inventory is temporarily unavailable.")
			return
		}
		entries, skipped, users := []protocol.SoftwareEntry{}, 0, []protocol.SoftwareUser{}
		if inv.Data != nil {
			entries, skipped = inv.Data.Entries, inv.Data.Skipped
			if inv.Data.Users != nil {
				users = inv.Data.Users
			}
		}
		writeJSON(w, http.StatusOK, struct {
			Info         devices.SoftwareView     `json:"info"`
			Entries      []protocol.SoftwareEntry `json:"entries"`
			Skipped      int                      `json:"skipped"`
			Users        []protocol.SoftwareUser  `json:"users"`
			History      []storage.SoftwareChange `json:"history"`
			HistoryLimit int                      `json:"history_limit"`
			HistoryDays  int                      `json:"history_days"`
		}{devices.PresentSoftware(inv, view, now), entries, skipped, users, history, storage.SoftwareHistoryLimit, storage.SoftwareHistoryDays})
	})

	// Signed-in sessions: the current sessions plus observed history.
	a.route(mux, "GET /api/v1/devices/{id}/sessions", deviceAccess("read"), func(w http.ResponseWriter, r *http.Request, s storage.Session) {
		_, view, ok := a.deviceView(w, r)
		if !ok {
			return
		}
		now := time.Now()
		current, e1 := a.store.Sessions(r.Context(), view.ID)
		history, e2 := a.store.SessionHistory(r.Context(), view.ID, now)
		if errors.Join(e1, e2) != nil {
			apiError(w, http.StatusServiceUnavailable, "unavailable", "Signed-in users are temporarily unavailable.")
			return
		}
		list := []protocol.Session{}
		if current.Data != nil {
			list = current.Data.Sessions
		}
		writeJSON(w, http.StatusOK, struct {
			Info         devices.SessionsView    `json:"info"`
			Sessions     []protocol.Session      `json:"sessions"`
			History      []storage.SessionRecord `json:"history"`
			HistoryLimit int                     `json:"history_limit"`
			HistoryDays  int                     `json:"history_days"`
		}{devices.PresentSessions(current, view, now), list, history, storage.SessionHistoryPage, storage.SessionHistoryDays})
	})

	// Logon history: logons from the Security log, newest first, with the
	// read permission.
	a.route(mux, "GET /api/v1/devices/{id}/logons", deviceAccess("read"), func(w http.ResponseWriter, r *http.Request, s storage.Session) {
		_, view, ok := a.deviceView(w, r)
		if !ok {
			return
		}
		q := r.URL.Query()
		f := storage.LogonFilter{Query: q.Get("q"), Kind: q.Get("kind")}
		if b := q.Get("before"); b != "" {
			at, record, found := strings.Cut(b, ":")
			t, e1 := strconv.ParseInt(at, 10, 64)
			n, e2 := strconv.ParseUint(record, 10, 64)
			if !found || e1 != nil || e2 != nil || t <= 0 {
				apiError(w, http.StatusBadRequest, "invalid_request", "Invalid page cursor.")
				return
			}
			f.Before, f.Record = t, n
		}
		if !storage.ValidLogonFilter(f) {
			apiError(w, http.StatusBadRequest, "invalid_request", "Invalid logon filter.")
			return
		}
		now := time.Now()
		status, e1 := a.store.LogonStatus(r.Context(), view.ID)
		list, more, e2 := a.store.Logons(r.Context(), view.ID, f, now)
		if errors.Join(e1, e2) != nil {
			apiError(w, http.StatusServiceUnavailable, "unavailable", "Logon history is temporarily unavailable.")
			return
		}
		writeJSON(w, http.StatusOK, struct {
			Info  storage.LogonStatus `json:"info"`
			Items []protocol.Logon    `json:"logons"`
			More  bool                `json:"more"`
			Page  int                 `json:"page"`
			Days  int                 `json:"days"`
		}{status, list, more, storage.LogonHistoryPage, storage.LogonHistoryDays})
	})

	// Local accounts and privileged group members.
	a.route(mux, "GET /api/v1/devices/{id}/local-accounts", deviceAccess("read"), func(w http.ResponseWriter, r *http.Request, s storage.Session) {
		_, view, ok := a.deviceView(w, r)
		if !ok {
			return
		}
		current, e := a.store.LocalAccounts(r.Context(), view.ID)
		if e != nil {
			apiError(w, http.StatusServiceUnavailable, "unavailable", "Local accounts are temporarily unavailable.")
			return
		}
		data := protocol.LocalAccounts{Accounts: []protocol.LocalAccount{}, Groups: []protocol.LocalGroup{}}
		if current.Data != nil {
			data = *current.Data
		}
		writeJSON(w, http.StatusOK, struct {
			Info     devices.LocalAccountsView `json:"info"`
			Accounts []protocol.LocalAccount   `json:"accounts"`
			Groups   []protocol.LocalGroup     `json:"groups"`
			Skipped  int                       `json:"skipped"`
		}{devices.PresentLocalAccounts(current, view, time.Now()), data.Accounts, data.Groups, data.Skipped})
	})

	// Metrics: bucketed CPU/RAM/disk history for a fixed range.
	metricWindow := func(w http.ResponseWriter, r *http.Request) (storage.MetricWindow, bool) {
		q := r.URL.Query()
		for k, v := range q {
			if k != "range" || len(v) != 1 {
				apiError(w, http.StatusBadRequest, "invalid_request", "Unknown metric option.")
				return storage.MetricWindow{}, false
			}
		}
		window, err := storage.MetricsWindow(q.Get("range"), time.Now())
		if err != nil {
			apiError(w, http.StatusBadRequest, "invalid_request", "Choose 24h, 7d or 30d.")
			return window, false
		}
		return window, true
	}
	a.route(mux, "GET /api/v1/devices/{id}/metrics", deviceAccess("read"), func(w http.ResponseWriter, r *http.Request, s storage.Session) {
		window, ok := metricWindow(w, r)
		if !ok {
			return
		}
		_, view, ok := a.deviceView(w, r)
		if !ok {
			return
		}
		h, e1 := a.store.MetricHistoryForSession(r.Context(), s, view.ID, window)
		summary, e2 := a.store.MetricSummariesForSession(r.Context(), s, []string{view.ID}, window)
		if errors.Join(e1, e2) != nil {
			apiError(w, http.StatusServiceUnavailable, "unavailable", "Metric history is temporarily unavailable.")
			return
		}
		writeJSON(w, http.StatusOK, struct {
			storage.MetricHistory
			Summary []storage.MetricBucket `json:"summary"`
		}{h, summary})
	})
	a.route(mux, "GET /api/v1/devices/{id}/metrics.csv", deviceAccess("read"), func(w http.ResponseWriter, r *http.Request, s storage.Session) {
		window, ok := metricWindow(w, r)
		if !ok {
			return
		}
		d, view, ok := a.deviceView(w, r)
		if !ok {
			return
		}
		h, e := a.store.MetricHistoryForSession(r.Context(), s, view.ID, window)
		if e != nil {
			apiError(w, http.StatusServiceUnavailable, "unavailable", "Metric history is temporarily unavailable.")
			return
		}
		writeMetricCSV(w, d.Hostname, window, h.Buckets)
	})

	// Windows Update: owner-only. Scans, installs from a fresh scan and
	// restarts all require the local broker and its own local permissions.
	a.route(mux, "GET /api/v1/devices/{id}/updates", ownerOnly, func(w http.ResponseWriter, r *http.Request, s storage.Session) {
		u, ok := a.loadUpdates(w, r)
		if ok {
			writeJSON(w, http.StatusOK, u)
		}
	})
	a.route(mux, "POST /api/v1/devices/{id}/updates", ownerOnly, func(w http.ResponseWriter, r *http.Request, s storage.Session) {
		var in struct {
			ID      string                    `json:"id"`
			Action  string                    `json:"action"`
			ScanID  string                    `json:"scan_id"`
			Updates []protocol.UpdateIdentity `json:"updates"`
		}
		if !decodeJSON(w, r, &in, 16384) {
			return
		}
		q := protocol.UpdateJob{ID: in.ID, Action: in.Action, ScanID: in.ScanID, Updates: in.Updates, ExpiresAt: time.Now().Add(time.Minute).Unix()}
		if q.Updates == nil {
			q.Updates = []protocol.UpdateIdentity{}
		}
		if !windowsupdate.JobValid(q) {
			apiError(w, http.StatusBadRequest, "invalid_request", "Choose a scan, up to 25 updates from the latest scan, or a restart.")
			return
		}
		u, ok := a.loadUpdates(w, r)
		if !ok {
			return
		}
		refuse := func(msg string) { apiError(w, http.StatusConflict, "refused", msg) }
		switch {
		case !u.Readiness.CanScan:
			refuse(u.Readiness.Reason)
			return
		case q.Action == "install" && !u.Readiness.CanInstall:
			refuse(u.Readiness.InstallReason)
			return
		case q.Action == "restart" && !u.Readiness.CanRestart:
			refuse(u.Readiness.RestartReason)
			return
		}
		if q.Action == "install" {
			if u.Scan == nil || q.ScanID != u.Scan.ID {
				refuse("The scan changed. Review the latest scan and select again.")
				return
			}
			for _, v := range q.Updates {
				found := false
				for _, c := range u.Scan.Catalog {
					if c.UpdateIdentity == v && c.Blocked == "" {
						found = true
					}
				}
				if !found {
					refuse("A selected update is no longer available or is blocked.")
					return
				}
			}
		}
		e := a.store.QueueUpdateJob(r.Context(), storage.UpdateJob{UpdateJob: q, DeviceID: u.DeviceID, Actor: s.Actor()}, time.Now(), a.offlineAfter())
		if e != nil {
			queueError(w, e, storage.ErrUpdateJob, "Windows Update operations are temporarily unavailable.")
			return
		}
		writeJSON(w, http.StatusAccepted, struct {
			ID string `json:"id"`
		}{q.ID})
	})
}

type updateScan struct {
	ID        string                   `json:"id"`
	CreatedAt int64                    `json:"created_at"`
	Fresh     bool                     `json:"fresh"`
	Truncated bool                     `json:"truncated"`
	Skipped   int                      `json:"skipped"`
	Newer     bool                     `json:"newer_scan_failed"`
	Catalog   []protocol.WindowsUpdate `json:"catalog"`
}

type updateReadiness struct {
	CanScan       bool   `json:"can_scan"`
	Reason        string `json:"reason"`
	CanInstall    bool   `json:"can_install"`
	InstallReason string `json:"install_reason"`
	CanRestart    bool   `json:"can_restart"`
	RestartReason string `json:"restart_reason"`
}

type updatesState struct {
	DeviceID  string                    `json:"device_id"`
	Support   devices.UpdateSupportView `json:"support"`
	Jobs      []storage.UpdateJob       `json:"jobs"`
	Pending   bool                      `json:"pending"`
	Scan      *updateScan               `json:"scan"`
	Readiness updateReadiness           `json:"readiness"`
	Policies  []storage.PatchPolicy     `json:"policies"`
	Guard     *storage.PatchGuard       `json:"guard"`
}

// loadUpdates projects retained scans and jobs. It never queues work.
func (a *api) loadUpdates(w http.ResponseWriter, r *http.Request) (updatesState, bool) {
	d, view, ok := a.deviceView(w, r)
	if !ok {
		return updatesState{}, false
	}
	if d.RevokedAt != nil {
		apiError(w, http.StatusNotFound, "not_found", "Device not found.")
		return updatesState{}, false
	}
	now := time.Now()
	support, e1 := a.store.UpdateSupport(r.Context(), d.ID)
	jobs, e2 := a.store.UpdateJobs(r.Context(), d.ID, now)
	policies, e3 := a.store.PatchPolicies(r.Context())
	guards, e4 := a.store.PatchGuards(r.Context())
	if errors.Join(e1, e2, e3, e4) != nil {
		apiError(w, http.StatusServiceUnavailable, "unavailable", "Windows Update details are temporarily unavailable.")
		return updatesState{}, false
	}
	u := updatesState{DeviceID: d.ID, Support: devices.PresentUpdateSupport(support, view, now), Jobs: jobs, Policies: []storage.PatchPolicy{}}
	newerFailed := false
	for _, q := range jobs {
		if q.Status == "queued" || q.Status == "dispatched" {
			u.Pending = true
		}
		if q.Action != "scan" || u.Scan != nil {
			continue
		}
		if q.Status == "succeeded" && q.Progress != nil {
			u.Scan = &updateScan{ID: q.ID, CreatedAt: q.CreatedAt, Fresh: q.CreatedAt > now.Add(-2*time.Hour).Unix() && q.CreatedAt <= now.Unix(), Truncated: q.Progress.Truncated, Skipped: q.Progress.Skipped, Newer: newerFailed, Catalog: q.Progress.Catalog}
		} else {
			newerFailed = true
		}
	}
	for _, p := range policies {
		for _, id := range p.Definition.Devices {
			if id == d.ID {
				u.Policies = append(u.Policies, p)
				break
			}
		}
	}
	for i := range guards {
		if guards[i].DeviceID == d.ID {
			u.Guard = &guards[i]
			break
		}
	}
	rd := &u.Readiness
	switch {
	case u.Support.Stale:
		rd.Reason = "The device has not reported Windows Update support recently."
	case u.Support.Data == nil || u.Support.Data.Broker != "available":
		rd.Reason = "Windows Update management is not available on this device. Update its agent."
	case u.Pending:
		rd.Reason = "Another update operation is still in progress."
	default:
		rd.CanScan = true
	}
	rd.InstallReason, rd.RestartReason = rd.Reason, rd.Reason
	if rd.CanScan {
		switch {
		case !u.Support.Data.CanInstall:
			rd.InstallReason = "This device's agent does not allow installing updates. Update its agent."
		case u.Scan == nil || !u.Scan.Fresh:
			rd.InstallReason = "Run a scan first; installs use a scan from the last two hours."
		default:
			rd.CanInstall = true
		}
		if u.Support.Data.CanRestart {
			rd.CanRestart = true
		} else {
			rd.RestartReason = "This device's agent does not allow restarts. Update its agent."
		}
	}
	return u, true
}

// Prefix text a spreadsheet could interpret as a formula; quoting alone does
// not prevent that.
func csvText(s string) string {
	t := strings.TrimLeftFunc(s, unicode.IsSpace)
	if strings.ContainsAny(s, "\t\r\n") || len(t) > 0 && strings.ContainsAny(t[:1], "=+-@") {
		return "'" + s
	}
	return s
}

func writeMetricCSV(w http.ResponseWriter, hostname string, window storage.MetricWindow, buckets []storage.MetricBucket) {
	stamp := func(v int64) string {
		if v == 0 {
			return ""
		}
		return time.Unix(v, 0).UTC().Format(time.RFC3339)
	}
	num := func(v *float64) string {
		if v == nil {
			return ""
		}
		return strconv.FormatFloat(*v, 'f', 2, 64)
	}
	w.Header().Set("Content-Type", "text/csv; charset=utf-8")
	w.Header().Set("Content-Disposition", `attachment; filename="openrmm-metrics-`+window.Range+`.csv"`)
	c := csv.NewWriter(w)
	_ = c.Write([]string{"device_id", "hostname", "metric", "bucket_utc", "bucket_seconds", "mean_percent", "min_percent", "max_percent", "valid_observations", "unavailable_reports", "detected_gaps", "first_observation_utc", "last_observation_utc"})
	for _, b := range buckets {
		if c.Write([]string{b.DeviceID, csvText(hostname), b.Kind, stamp(b.At), strconv.FormatInt(window.Step, 10), num(b.Mean), num(b.Min), num(b.Max), strconv.FormatInt(b.Count, 10), strconv.FormatInt(b.Unknown, 10), strconv.FormatInt(b.Gaps, 10), stamp(b.First), stamp(b.Last)}) != nil {
			return
		}
	}
	c.Flush()
}
